.getvalue())) failed = True print("Test: quiet still suppresses progress in both modes") if make_progress(quiet=True, machine=False) is not None: print(" ERROR: quiet should give no progress callback") failed = True if make_progress(quiet=True, machine=True) is not None: print(" ERROR: quiet should give no progress callback in machine mode either") failed = True return failed Register it in apps/predbat/unit_test.py : from tests.test_annual_cli import test_annual_cli, test_annual_cli_machine ("annual_cli_machine", test_annual_cli_machine, "Annual CLI machine mode tests", False), [ ] Step 2: Run the test to verify it fails Run: cd coverage && ./run_all --test annual_cli_machine > /tmp/w2.txt 2>&1; grep -E "ERROR|TypeError|cannot import" /tmp/w2.txt Expected: FAIL — make_progress() does not yet accept machine . [ ] Step 3: Add machine mode to apps/predbat/annual_cli.py Replace make_progress with: def make_progress(quiet, machine=False): """Return a progress callback writing to stderr, or None when quiet. Machine mode emits one JSON object per line so the parent process never has to parse prose - the human wording is free to change without breaking a caller. Progress always goes to stderr so stdout carries only the result, whichever mode is in use. """ if quiet: return None if machine: def progress(completed, total, message): """Emit one JSON progress record to stderr.""" sys.stderr.write(json.dumps({"completed": completed, "total": total, "message": message}) + "
") sys.stderr.flush() return progress def progress(completed, total, message): """Report progress to stderr so stdout stays parseable.""" sys.stderr.write("[{}/{}] {}
".format(completed, total, message)) sys.stderr.flush() return progress Add the flag in main() , beside the existing arguments: parser.add_argument("--machine", action="store_true", help="Emit results as JSON on stdout and progress as JSON on stderr, for a calling process") Pass it through where the progress callback is built: results = asyncio.run(predictor.run(progress=make_progress(args.quiet, machine=args.machine))) Then replace the output section at the end of main() so machine mode emits JSON and suppresses the table: if args.out: try: with open(args.out, "w", encoding="utf-8") as handle: json.dump(results, handle, indent=2) except (OSError, TypeError, ValueError) as error: sys.stderr.write("Could not write results to {}: {}
".format(args.out, error)) exit_code = 1 if args.machine: # The parent reads exactly one JSON object from stdout; the human table would # corrupt it, so it is suppressed rather than merely reordered. json.dump(results, sys.stdout) sys.stdout.write("
") else: print(format_table(results)) return exit_code Ensure import json and import sys are present at the top of the file. [ ] Step 4: Run the tests to verify they pass Run: cd coverage && ./run_all -k annual_cli > /tmp/w2.txt 2>&1; grep -E "ERROR|Traceback" /tmp/w2.txt Expected: no output; both annual_cli and annual_cli_machine pass. [ ] Step 5: Verify machine mode by hand cd coverage && echo "annual: {}" > /tmp/bad.yaml && ./venv/bin/python3 ../apps/predbat/annual_cli.py --config /tmp/bad.yaml --machine; echo "exit=$?" Expected: a readable config error on stderr and exit=2 , with nothing on stdout — a parent parsing stdout must not receive half a document on failure. Put the actual output in your report. [ ] Step 6: Run pre-commit and commit git add apps/predbat/annual_cli.py apps/predbat/tests/test_annual_cli.py apps/predbat/unit_test.py coverage/venv/bin/pre-commit run --files apps/predbat/annual_cli.py apps/predbat/tests/test_annual_cli.py apps/predbat/unit_test.py git commit -m "feat(annual): add machine mode so a parent process can drive the CLI"

