elf._body = body or {} async def json(self): """Return the decoded JSON body.""" return self._body def _make_web(my_predbat, agent=None): """Build a WebInterface bound to my_predbat without standing up the aiohttp app.""" interface = WebInterface.__new__(WebInterface) interface.base = my_predbat interface.log = my_predbat.log interface.prefix = my_predbat.prefix interface.registered_endpoints = [] interface.chat_page = WebChat(interface) interface.chat_page.agent_override = agent return interface def test_routes_registered_only_when_enabled(my_predbat): """The chat routes and nav link appear only when the component is configured.""" failed = False print("**** Testing chat route registration ****") class NoChat: """A components registry with no chat component.""" def get_component(self, name): """Return nothing for every component.""" return None class WithChat: """A components registry that has a chat component.""" def get_component(self, name): """Return a stand-in component for 'chat' only.""" return object() if name == "chat" else None interface = _make_web(my_predbat) my_predbat.components = NoChat() if interface.chat_enabled(): print("ERROR: chat reported as enabled with no component") failed = True app = aiohttp_web.Application() interface._register_chat_routes(app) if [route for route in app.router.routes() if "/chat" in str(route.resource)]: print("ERROR: chat routes were registered with no component") failed = True my_predbat.components = WithChat() if not interface.chat_enabled(): print("ERROR: chat reported as disabled with a component present") failed = True app = aiohttp_web.Application() interface._register_chat_routes(app) paths = {str(route.resource.canonical) for route in app.router.routes()} for expected in ["/chat", "/chat/conversations", "/chat/history", "/chat/send", "/chat/stream", "/chat/confirm", "/chat/cancel", "/chat/delete", "/chat/rename", "/chat/models", "/chat/model"]: if expected not in paths: print("ERROR: route {} was not registered,