nversation returned {}, expected 404".format(history.status)) failed = True return failed def test_delete_refuses_the_active_conversation(my_predbat): """The conversation with the running turn cannot be deleted out from under it.""" failed = False print("**** Testing delete of the active conversation ****") class BusyAgent: """An agent stand-in mid-turn in a known conversation.""" active = {"conversation_id": "aaaabbbbccccdddd", "turn_id": 1, "title": "busy one"} class store: """A store stand-in that knows the busy conversation.""" @staticmethod def get_meta(cid): """Resolve the busy conversation.""" return {"id": cid, "title": "busy one"} if cid == "aaaabbbbccccdddd" else None page = _make_web(my_predbat, agent=BusyAgent()).chat_page response = asyncio.run(page.html_chat_delete(FakeRequest(body={"id": "aaaabbbbccccdddd"}))) if response.status != 409: print("ERROR: deleting the active conversation returned {}, expected 409".format(response.status)) failed = True return failed def test_sse_framing(my_predbat): """Events are framed with id/event/data lines and JSON-encoded payloads.""" failed = False print("**** Testing SSE framing ****") frame = format_sse_event({"seq": 7, "conversation_id": "abcd", "type": "delta", "data": {"text": "hi
